// === Tab: shader ===
//DEFINE SHADER
let vs = `
  precision highp float;
  attribute vec3 aPosition;

  void main() {
     vec4 positionVec4 = vec4(aPosition, 1.0);
     gl_Position = positionVec4;
}
`;
let fs = `
  precision highp float;

  uniform vec2 resolution;
	uniform sampler2D SkyboxTexture;
	const float MaxRenderDistance = 10000.0;

	//RAYS
	struct Ray
	{
		vec3 origin;
		vec3 direction;
		float energy;
	};
	Ray CameraRay(vec2 coord)
	{
		vec2 uv = coord/resolution.xy - vec2(0.5);
		uv.x *= resolution.x / resolution.y;

		vec3 origin = vec3(0,0,0);
		vec3 direction = normalize(vec3(uv.x, uv.y, -1.0));
		return Ray(origin, direction, 1.0);
	}

	//HITS
	struct Hit
	{
		vec3 colour;
		vec3 point;
		vec3 normal;
		float distance;
		float specular;
	};
	Hit EmptyHit()
	{
		return Hit(vec3(0,0,0), vec3(0,0,0), vec3(0,0,0), MaxRenderDistance, 0.0);
	}
	float QDST(vec3 a)
	{
		return (a.x*a.x) + (a.y*a.y) + (a.z*a.z);
	}

	void IntersectGround(Ray ray, inout Hit hit, float height)
	{

	}
	void IntersectBox(Ray ray, inout Hit hit, vec3 centre, vec3 colour, float specular)
	{
		vec3 bMin = centre-vec3(0.5,0.5,0.5);
		vec3 bMax = centre+vec3(0.5,0.5,0.5);

		vec3 tMin = (bMin-ray.origin) / ray.direction;
		vec3 tMax = (bMax-ray.origin) / ray.direction;

		float txEnter = min(tMin.x, tMax.x);
		float tyEnter = min(tMin.y, tMax.y);

		float txExit = max(tMin.x, tMax.x);
		float tyExit = max(tMin.y, tMax.y);

		float tzEnter = min(tMin.z, tMax.z);
		float tzExit = max(tMin.z, tMax.z);

		float tEnter = max(tzEnter,max(txEnter, tyEnter));
		float tExit = min(tzExit,min(txExit, tyExit));

		if (tEnter < hit.distance && tEnter < tExit)
		{
			vec3 point = ray.direction * tEnter+ray.origin;
			if (dot(ray.direction, point-ray.origin) < 0.0)
				return;

			//ray parametrics
			hit.point = point;
			hit.distance = tEnter;

			//calculate normal
			vec3 CTP = hit.point - centre;
			vec3 AbsCTP = vec3(abs(CTP.x), abs(CTP.y), abs(CTP.z));
			float biggestCTP = max(max(AbsCTP.x,AbsCTP.y), AbsCTP.z);
			if (AbsCTP.x == biggestCTP)
				hit.normal = vec3(sign(CTP.x), 0, 0);
			else if (AbsCTP.y == biggestCTP)
				hit.normal = vec3(0, sign(CTP.y), 0);
			else if (AbsCTP.z == biggestCTP)
				hit.normal = vec3(0,0,sign(CTP.z));

			//give colour
			float lightCosine =  max(0.1,dot(normalize(vec3(0.4,1,1)), hit.normal));
			hit.colour = colour * vec3(lightCosine);
			hit.specular = specular;
		}
	}

	vec3 SampleSkybox(vec3 dir)
	{
		float PI = 3.14159265;
		float theta = acos(dir.y) / PI;
		float phi = atan(dir.x / -dir.z) / -PI * 0.5;
		if (phi < 0.0)
			phi= abs(phi);
		vec4 c = texture2D(SkyboxTexture, vec2(phi, theta));
		return vec3(c.x,c.y,c.z);
	}

	//INTERSECTIONS
	void Intersect(inout Ray ray, inout Hit hit)
	{
		Hit returnHit = EmptyHit();
		IntersectBox(ray, returnHit, vec3(3,0,-3), vec3(1,1,1), 0.3);
		IntersectBox(ray, returnHit, vec3(1,0,-3), vec3(0.8,0.2,0.2), 0.1);
		IntersectGround(ray, returnHit, -1.0);

		if (returnHit.distance < MaxRenderDistance)
		{
			//set hit information
			hit.colour += returnHit.colour;
			hit.normal = returnHit.normal;
			hit.point = returnHit.point;
			ray.energy *= returnHit.specular;
		}
		else
		{
			//return skybox colour
			hit.colour = SampleSkybox(ray.direction);
			hit.distance = -1.0;
		}

		//return ray information
		ray.origin = hit.point + hit.normal*0.001;
		ray.direction = reflect(ray.direction, hit.normal);
	}

  void main() {
		Ray viewRay = CameraRay(gl_FragCoord.xy);
		vec3 colour = vec3(0,0,0);
		float importance = 1.0;
		for (int i =0 ; i < 10; i++)
		{
			Hit hit = EmptyHit();
			Intersect(viewRay, hit);
			colour += hit.colour * importance;
			importance *= viewRay.energy;
			if (hit.distance < 0.0 || importance < 0.001)
				break;
		}

    gl_FragColor = vec4(colour,1);
}
`;

